package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	"github.com/hashicorp/terraform-plugin-sdk/v2/plugin"
	ldap "github.com/go-ldap/ldap/v3"
)

func Provider() *schema.Provider {
	return &schema.Provider{
		Schema: map[string]*schema.Schema{
			"ldap_url": {Type: schema.TypeString, Required: true},
			"bind_dn":  {Type: schema.TypeString, Required: true},
			"bind_password": {Type: schema.TypeString, Required: true, Sensitive: true},
			"hsm_slot_id": {Type: schema.TypeString, Optional: true},
		},
		ResourcesMap: map[string]*schema.Resource{
			"ldaporg_group_membership": resourceGroupMembership(),
		},
		ConfigureContextFunc: providerConfigure,
	}
}

type apiClient struct {
	conn     *ldap.Conn
	baseDN   string
	hsmSlot  string
}

func providerConfigure(ctx context.Context, d *schema.ResourceData) (interface{}, diag.Diagnostics) {
	url := d.Get("ldap_url").(string)
	bindDN := d.Get("bind_dn").(string)
	bindPW := d.Get("bind_password").(string)
	hsmSlot := d.Get("hsm_slot_id").(string)

	conn, err := ldap.DialURL(url)
	if err != nil {
		return nil, diag.FromErr(err)
	}

	err = conn.Bind(bindDN, bindPW)
	if err != nil {
		return nil, diag.FromErr(err)
	}

	// Extract base DN from bind DN
	parts := strings.Split(bindDN, ",")
	baseDN := strings.Join(parts[1:], ",")

	return &apiClient{conn: conn, baseDN: baseDN, hsmSlot: hsmSlot}, nil
}

func resourceGroupMembership() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceGroupMembershipCreate,
		ReadContext:   resourceGroupMembershipRead,
		DeleteContext: resourceGroupMembershipDelete,
		Schema: map[string]*schema.Schema{
			"group_name": {Type: schema.TypeString, Required: true, ForceNew: true},
			"username":   {Type: schema.TypeString, Required: true, ForceNew: true},
		},
	}
}

func resourceGroupMembershipRead(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	client := m.(*apiClient)
	groupName := d.Get("group_name").(string)
	username := d.Get("username").(string)

	// VULNERABILITY: Direct string interpolation into LDAP filter
	// No sanitization of groupName or username inputs
	filter := fmt.Sprintf("(&(cn=%s)(member=uid=%s,%s))", groupName, username, client.baseDN)

	searchReq := ldap.NewSearchRequest(
		client.baseDN,
		ldap.ScopeWholeSubtree,
		ldap.NeverDerefAliases,
		0, 0, false,
		filter,
		[]string{"cn", "member"},
		nil,
	)

	result, err := client.conn.Search(searchReq)
	if err != nil {
		return diag.FromErr(err)
	}

	if len(result.Entries) == 0 {
		d.SetId("")
	}
	return nil
}

func resourceGroupMembershipCreate(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	client := m.(*apiClient)
	groupName := d.Get("group_name").(string)
	username := d.Get("username").(string)

	// Construct DN for the group - also injectable
	groupDN := fmt.Sprintf("cn=%s,%s", groupName, client.baseDN)

	modifyReq := ldap.NewModifyRequest(groupDN, nil)
	memberDN := fmt.Sprintf("uid=%s,%s", username, client.baseDN)
	modifyReq.Add("member", []string{memberDN})

	if err := client.conn.Modify(modifyReq); err != nil {
		return diag.FromErr(err)
	}

	d.SetId(fmt.Sprintf("%s/%s", groupName, username))
	return resourceGroupMembershipRead(ctx, d, m)
}

func resourceGroupMembershipDelete(ctx context.Context, d *schema.ResourceData, m interface{}) diag.Diagnostics {
	client := m.(*apiClient)
	groupName := d.Get("group_name").(string)
	username := d.Get("username").(string)

	groupDN := fmt.Sprintf("cn=%s,%s", groupName, client.baseDN)
	memberDN := fmt.Sprintf("uid=%s,%s", username, client.baseDN)

	modifyReq := ldap.NewModifyRequest(groupDN, nil)
	modifyReq.Delete("member", []string{memberDN})

	if err := client.conn.Modify(modifyReq); err != nil {
		log.Printf("[WARN] Failed to remove member %s from group %s: %v", username, groupName, err)
	}

	d.SetId("")
	return nil
}

func main() {
	plugin.Serve(&plugin.ServeOpts{
		ProviderFunc: Provider,
	})
}
